import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"Frequently Asked Questions","description":"Common questions about Hearth and Coding Agents, Codex wrappers, internet access, Phase 1 capabilities, side effects, evolution, multi-user support, mobile, and bilingual documentation.","frontmatter":{"title":"Frequently Asked Questions","description":"Common questions about Hearth and Coding Agents, Codex wrappers, internet access, Phase 1 capabilities, side effects, evolution, multi-user support, mobile, and bilingual documentation.","outline":[2,3]},"headers":[],"relativePath":"en/reference/faq.md","filePath":"en/reference/faq.md","lastUpdated":1793797632000}'),n={name:"en/reference/faq.md"};function r(s,e,l,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<p class="eyebrow">FAQ</p><h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><p class="lead">This page answers the questions most likely to come up when first encountering Hearth. For more complete definitions and boundaries, see [Design and Tradeoffs](/en/design/) and [Architecture Overview](/en/architecture/overview).</p><h2 id="is-hearth-another-coding-agent" tabindex="-1">Is Hearth another Coding Agent? <a class="header-anchor" href="#is-hearth-another-coding-agent" aria-label="Permalink to &quot;Is Hearth another Coding Agent?&quot;">​</a></h2><p>No. Codex is an important peer Executor for Hearth, but Hearth&#39;s product center is Task control, durable execution, memory, verification, approval, and Receipts. It is meant to handle a broader range of personal digital labor, including email, documents, schedules, the web, desktops, and data.</p><h2 id="is-it-a-codex-wrapper" tabindex="-1">Is it a Codex wrapper? <a class="header-anchor" href="#is-it-a-codex-wrapper" aria-label="Permalink to &quot;Is it a Codex wrapper?&quot;">​</a></h2><p>No. Hearth does not treat Codex as its sole execution brain, nor does it let Codex hold long-lived credentials, become the memory hub, or expand its own permissions. Codex receives minimal context through a Task Pack and returns Artifacts, verification, and failure classification via structured output.</p><h2 id="does-it-require-an-internet-connection" tabindex="-1">Does it require an internet connection? <a class="header-anchor" href="#does-it-require-an-internet-connection" aria-label="Permalink to &quot;Does it require an internet connection?&quot;">​</a></h2><p>Local-first by default. State, events, memory, and credentials are stored locally first; model APIs, remote Sandbox, and cloud sync are all optional capabilities. For specific deployment forms, see <a href="/hearth-os/en/architecture/overview.html">Overall Architecture</a>.</p><h2 id="what-can-phase-1-do" tabindex="-1">What can Phase 1 do? <a class="header-anchor" href="#what-can-phase-1-do" aria-label="Permalink to &quot;What can Phase 1 do?&quot;">​</a></h2><p>Phase 1 delivers the Hearth MVP: recoverable task state, real execution, Web task cards, approval drills, artifacts, and failure recovery. It does not include email, calendar, desktop operation, proactive loops, full memory, or multi-device.</p><h2 id="why-not-just-build-an-all-purpose-agent" tabindex="-1">Why not just build an all-purpose Agent? <a class="header-anchor" href="#why-not-just-build-an-all-purpose-agent" aria-label="Permalink to &quot;Why not just build an all-purpose Agent?&quot;">​</a></h2><p>Because “all-purpose” usually means permissions, context, and failure boundaries are all uncontrollable. Hearth chooses multiple peer Executors, routed by capability, risk, and Token cost; each Executor has clear boundaries, a verifier, and a takeover path.</p><h2 id="how-are-external-side-effects-prevented-from-being-duplicated" tabindex="-1">How are external side effects prevented from being duplicated? <a class="header-anchor" href="#how-are-external-side-effects-prevented-from-being-duplicated" aria-label="Permalink to &quot;How are external side effects prevented from being duplicated?&quot;">​</a></h2><p>All external actions go through an outbox, idempotency keys, approval/authorization checks, and a Receipt. Persist first, then execute; retries reuse the same idempotency key; non-idempotent external actions must be approved and handed off to a human; reconcile uncertain results first.</p><h2 id="will-hearth-modify-itself-automatically" tabindex="-1">Will Hearth modify itself automatically? <a class="header-anchor" href="#will-hearth-modify-itself-automatically" aria-label="Permalink to &quot;Will Hearth modify itself automatically?&quot;">​</a></h2><p>There is no unbounded self-modification. Evolution OS can only produce candidate skills or candidate Policies, which must go through evaluation, canary, promotion, and rollback. Changes to the core Runtime still require a manual PR.</p><h2 id="does-it-support-multiple-users-or-enterprises" tabindex="-1">Does it support multiple users or enterprises? <a class="header-anchor" href="#does-it-support-multiple-users-or-enterprises" aria-label="Permalink to &quot;Does it support multiple users or enterprises?&quot;">​</a></h2><p>Not a first-version goal. Hearth is a single-user, self-hosted product; enterprise IAM, multi-tenancy, organizational audit, and billing are explicitly not promised.</p><h2 id="can-it-be-used-on-mobile" tabindex="-1">Can it be used on mobile? <a class="header-anchor" href="#can-it-be-used-on-mobile" aria-label="Permalink to &quot;Can it be used on mobile?&quot;">​</a></h2><p>Mobile is a Phase 4 focus: viewing, approval, takeover, initiation, and notifications. Mobile is not a full Agent replica but a controlled entry point.</p><h2 id="why-are-there-two-versions-of-the-documentation-in-chinese-and-english" tabindex="-1">Why are there two versions of the documentation, in Chinese and English? <a class="header-anchor" href="#why-are-there-two-versions-of-the-documentation-in-chinese-and-english" aria-label="Permalink to &quot;Why are there two versions of the documentation, in Chinese and English?&quot;">​</a></h2><p>Chinese is the source language of the current roadmap, and English is for broader developer readership. Both sets of pages keep the same paths and structure, with one-click switching in the upper right. If you find translation or structure issues, see <a href="/hearth-os/en/reference/contributing.html">Contribution and Documentation Maintenance</a>.</p>',23)])])}const m=a(n,[["render",r]]);export{p as __pageData,m as default};
